// English fallback for hosts without plugin i18n, and for any missing key.
function enT(key, ...args) {
  const v = key.split('.').reduce((n, p) => (n && typeof n === 'object' ? n[p] : undefined), EN)
  return typeof v === 'function' ? v(...args) : typeof v === 'string' ? v : key
}
const useT = () => usePluginI18n(ID)

// --- shared bits ---------------------------------------------------------------

// Load over the last 24 hours, from Calm triggers. Unknown values fall back to clear.
const LOAD = { clear: { bars: 1, why: 'whyClear' }, rising: { bars: 2, why: 'whyRising' }, high: { bars: 3, why: 'whyHigh' } }
const loadKey = v => (Object.hasOwn(LOAD, v) ? v : 'clear')

// The glyph: the approved round-14 E shard (docs/DESIGN-PREFLIGHT.md §8). A thick
// raw satin-spar shard set diagonally, off-centre tip, fibres along its length.
// Static identity, never a state indicator.
function Blade({ size = 16, title }) {
  return jsxs('svg', {
    className: 'sel-glyph', width: size, height: size, viewBox: '0 0 24 24',
    role: title ? 'img' : undefined, 'aria-label': title, 'aria-hidden': title ? undefined : true,
    children: [
      jsx('path', { d: 'M2.6 17.4 15.9 3.9 21.3 2.6 20.6 8.3 7.2 21.5 4.9 21 4.4 19.6 2.9 19.1Z', fill: 'currentColor', fillOpacity: 0.92 }),
      jsx('path', { d: 'M5.4 18.6 17.9 5.9M8.3 19.5 19.6 8.1', stroke: 'var(--ui-bg-card, #000)', strokeOpacity: 0.4, strokeWidth: 0.9, strokeLinecap: 'round' })
    ]
  })
}

function Meter({ load }) {
  return jsx('span', { className: 'sel-meter', 'aria-hidden': true,
    children: [1, 2, 3].map(i => jsx('i', { 'data-on': i <= LOAD[loadKey(load)].bars ? '' : undefined }, i)) })
}

function Spark({ series, k }) {
  const vals = series.map(d => Number(d?.[k]) || 0)
  const max = Math.max(1, ...vals)
  const w = 100 / Math.max(1, vals.length)
  const fill = k === 'calm' ? 'var(--sel-load)' : k === 'approval' ? 'var(--sel-appr)' : 'var(--sel-gate)'
  return jsx('svg', {
    className: 'sel-spark', viewBox: '0 0 100 24', preserveAspectRatio: 'none', 'aria-hidden': true,
    children: vals.map((v, i) => jsx('rect', {
      x: i * w + w * 0.15, width: w * 0.7, y: 24 - Math.max(v ? 2 : 1, (v / max) * 24), height: Math.max(v ? 2 : 1, (v / max) * 24),
      rx: 0.6, fill: v ? fill : 'var(--ui-stroke-tertiary)'
    }, i))
  })
}

// Proposal markdown is our own evolve.py output: headings, bullets, inline code.
function Inline({ text }) {
  return jsx(Fragment, { children: text.split(/(`[^`]+`)/).map((t, i) =>
    t.startsWith('`') && t.endsWith('`') ? jsx('code', { children: t.slice(1, -1) }, i) : t) })
}
function Proposal({ text, label }) {
  const out = []
  let list = null
  String(text).split('\n').forEach((line, i) => {
    if (line.startsWith('- ')) {
      list ??= []
      list.push(jsx('li', { children: jsx(Inline, { text: line.slice(2) }) }, i))
      return
    }
    if (list) { out.push(jsx('ul', { children: list }, `u${i}`)); list = null }
    if (line.startsWith('# ') || !line.trim()) return
    out.push(line.startsWith('## ')
      ? jsx('h3', { children: line.slice(3) }, i)
      : jsx('p', { children: jsx(Inline, { text: line }) }, i))
  })
  if (list) out.push(jsx('ul', { children: list }, 'end'))
  // A scroll region must be reachable by keyboard.
  return jsx('div', { className: 'sel-prop', tabIndex: 0, role: 'region', 'aria-label': label, children: out })
}

// Stable keys for rows that can share a timestamp.
function keyed(list, f) {
  const seen = new Map()
  return list.map(x => {
    const base = f(x)
    const n = seen.get(base) ?? 0
    seen.set(base, n + 1)
    return [n ? `${base}#${n}` : base, x]
  })
}

const fail = what => err => host.notifyError(err, what)
const Retry = ({ onClick, t }) => jsx(Button, { size: 'sm', variant: 'secondary', onClick, children: t('err.retry') })

// --- page ------------------------------------------------------------------

function SelenitePage({ ctx, prefs, update, refreshStatus }) {
  const t = useT()
  const ago = ts => (ts ? relativeTime(ts * 1000) : t('never'))
  // Ledger kinds in words; an unknown kind shows as logged.
  const kindLabel = k => { const v = t(`kinds.${k}`); return !v || v === `kinds.${k}` ? k : v }
  const { days } = useValue(prefs)
  const qc = useQueryClient()
  const overview = useQuery({ queryKey: [ID, 'overview', days], queryFn: () => ctx.rest(`/overview?days=${days}`), refetchInterval: 30_000 })
  const events = useQuery({ queryKey: [ID, 'events', days], queryFn: () => ctx.rest(`/events?days=${days}&limit=40`), refetchInterval: 30_000 })
  const proposal = useQuery({ queryKey: [ID, 'proposal'], queryFn: () => ctx.rest('/proposal') })
  const cleanse = useQuery({ queryKey: [ID, 'cleanse'], queryFn: () => ctx.rest('/cleanse') })
  const fake = useQuery({ queryKey: [ID, 'fake', days], queryFn: () => ctx.rest(`/fake-gates/overview?days=${Math.min(days, 90)}&top=6`), refetchInterval: 60_000 })
  const refresh = () => { qc.invalidateQueries({ queryKey: [ID] }); refreshStatus() }
  const log = (kind, key, note) => ctx.rest('/events', { method: 'POST', body: { kind, key, note } })
  const markFix = useMutation({
    mutationFn: key => log('fix', key, 'marked fixed in Selenite'),
    onSuccess: (_, key) => {
      refresh()
      host.notify({ kind: 'success', message: t('gates.marked', key), action: { label: t('gates.undo'), onClick: () => log('reopen', key, 'undo in Selenite').then(refresh, fail(t('err.undo'))) } })
    },
    onError: fail(t('err.fix'))
  })
  const sweep = useMutation({ mutationFn: () => ctx.rest(`/cleanse?days=${days}`, { method: 'POST' }), onSuccess: refresh, onError: fail(t('err.cleanse')) })
  const draft = useMutation({ mutationFn: () => ctx.rest(`/proposal?days=${days}`, { method: 'POST' }), onSuccess: refresh, onError: fail(t('err.draft')) })
  const shell = children => jsx('div', { className: 'sel-host', children: jsx('div', { className: 'sel', children }) })

  const head = jsxs('header', { className: 'sel-head', children: [
    jsxs('div', { className: 'sel-mark', children: [
      jsx(Blade, { size: 26 }),
      jsxs('div', { children: [
        jsx('h1', { className: 'sel-word', children: t('name') }),
        jsx('div', { className: 'sel-sub', children: t('tagline') })
      ] })
    ] }),
    jsx(SegmentedControl, {
      value: String(days), onChange: v => update({ days: Number(v) }), 'aria-label': t('window.label'),
      options: [{ id: '7', label: t('window.d7') }, { id: '30', label: t('window.d30') }, { id: '90', label: t('window.d90') }]
    })
  ] })

  const o = overview.data
  if (!o) {
    // No data yet: a full error state with Retry, or loading skeletons.
    return shell([head, overview.isError
      ? jsx('div', { className: 'sel-card', role: 'alert', children: jsx(ErrorState, { title: t('err.downTitle'), description: t('err.down'), children: jsx(Retry, { t, onClick: () => overview.refetch() }) }) })
      : jsxs(Fragment, { children: [
          jsx(Skeleton, { style: { height: 64, borderRadius: 10 } }),
          jsx('div', { className: 'sel-stats', children: [0, 1, 2, 3].map(i => jsx(Skeleton, { style: { height: 104, borderRadius: 10 } }, i)) }),
          jsx(Skeleton, { style: { height: 320, borderRadius: 10 } })
        ] })])
  }
  // A failed refetch keeps the last good data and shows a retry strip.
  const warn = overview.isError && jsxs('div', { className: 'sel-warn', role: 'alert', children: [
    jsx('span', { children: t('err.stale') }), jsx(Retry, { t, onClick: () => overview.refetch() })
  ] })

  const tot = o.totals ?? {}
  const gates = Array.isArray(o.gates) ? o.gates : []
  const series = Array.isArray(o.series) ? o.series : []
  const lk = loadKey(o.load)
  const maxN = Math.max(1, ...gates.map(g => Number(g.n) || 0))
  const stat = (label, n, k, sub) => jsxs('div', { className: 'sel-card sel-stat', children: [
    jsx('h3', { className: 'sel-label', children: label }),
    jsxs('div', { className: 'sel-num', children: [n ?? 0, sub && jsx('small', { children: sub })] }),
    k ? jsx(Spark, { series, k }) : jsx('div', { className: 'sel-sub', style: { marginTop: 0, minHeight: 24 }, children: gates.length ? t('stats.fixedOf', gates.filter(g => g.fixed).length, gates.length) : t('stats.noneToFix') })
  ] })
  const sec = (id, title, sub, body) => jsxs('section', { className: 'sel-card sel-sec', 'aria-labelledby': id, children: [
    jsxs('div', { className: 'sel-sec-head', children: [jsx('h2', { id, className: 'sel-label', children: title }), sub && jsx('span', { className: 'sel-sub', style: { marginTop: 0 }, children: sub })] }),
    ...body
  ] })
  const evs = events.data?.events ?? []
  const cl = cleanse.data?.cleanse
  const finds = Array.isArray(cl?.findings) ? cl.findings : []
  const stones = Object.entries(cl?.by_stone ?? {}).sort((a, b) => b[1] - a[1])
  const swept = cl?.generated ? relativeTime(Date.parse(cl.generated)) : ''
  const top = finds[0]
  const cleanseSec = sec('sel-cleanse-h', t('cleanse.title'), cl ? t('cleanse.swept', cl.total ?? finds.length, stones.length, swept) : t('cleanse.none'), [
    cleanse.isError && !cleanse.data
      ? jsxs('p', { className: 'sel-inline', role: 'alert', children: [t('err.cleanseLoad'), jsx(Retry, { t, onClick: () => cleanse.refetch() })] }, 'x')
      : !cl
        ? jsx('p', { className: 'sel-load-why', style: { margin: 0 }, children: t('cleanse.about') }, 'a')
        : !top
          ? jsxs('p', { className: 'sel-inline', children: [jsx('span', { className: 'sel-fixed', children: t('cleanse.clean') })] }, 'c')
          : jsxs('div', { className: 'sel-next', children: [
              jsxs('div', { className: 'sel-next-top', children: [jsx('h3', { className: 'sel-label', style: { color: 'var(--ui-text-primary)' }, children: t('cleanse.clearNext') }), jsx('span', { className: 'sel-tag', children: top.stone })] }),
              jsxs('div', { style: { minWidth: 0, display: 'flex', flexDirection: 'column', gap: 6 }, children: [
                jsx('p', { className: 'sel-next-problem', children: top.problem }),
                jsxs('p', { className: 'sel-next-fix', children: [jsx('b', { children: t('cleanse.where') }), ' ', jsx('span', { className: 'sel-key', children: top.where })] }),
                jsxs('p', { className: 'sel-next-fix', children: [jsx('b', { children: t('cleanse.fix') }), ' ', top.fix] })
              ] }),
              Number(top.interruptions) > 0 ? jsxs('div', { className: 'sel-next-n', children: [top.interruptions, jsx('small', { children: t('cleanse.hits', Number(top.interruptions)) })] }) : null
            ] }, 'n'),
    finds.length > 1 && jsxs('div', { className: 'sel-sec', style: { gap: 6 }, children: [
      jsx('h3', { className: 'sel-label', children: t('cleanse.more') }),
      jsx('ol', { className: 'sel-rows', children: keyed(finds.slice(1, 6), f => `${f.stone}-${f.where}-${f.check}`).map(([k, f]) => jsxs('li', { className: 'sel-find', children: [
        jsx('span', { className: 'sel-tag', children: f.stone }),
        jsxs('div', { style: { minWidth: 0 }, children: [jsx('div', { style: { fontSize: 12.5 }, children: f.problem }), jsx('div', { className: 'sel-key sel-note', style: { fontSize: 11.5 }, children: f.where })] }),
        jsx('span', { className: 'sel-count', children: Number(f.interruptions) > 0 ? `×${f.interruptions}` : '' })
      ] }, k)) })
    ] }, 'm'),
    stones.length > 0 && jsx('ul', { className: 'sel-stones', 'aria-label': t('cleanse.byStone'), children: stones.map(([k, n]) => jsxs('li', { className: 'sel-tag', children: [k, jsx('b', { children: n })] }, k)) }, 's'),
    cl?.errors?.length ? jsx('p', { className: 'sel-sub', style: { margin: 0 }, children: t('cleanse.errors', cl.errors.length) }, 'r') : null,
    jsxs('div', { className: 'sel-actions', children: [
      jsx(Button, { size: 'sm', variant: 'secondary', disabled: sweep.isPending, onClick: () => sweep.mutate(), children: sweep.isPending ? t('cleanse.running') : t('cleanse.run') }),
      jsx(CopyButton, { text: '/frictionless cleanse', label: t('cleanse.copy'), showLabel: true, appearance: 'button', buttonVariant: 'ghost', buttonSize: 'sm' })
    ] }, 'b')
  ])
  const fg = fake.data
  const fgCards = Array.isArray(fg?.cards) ? fg.cards : []
  const fakeSec = sec('sel-fake-h', t('fake.title'), t('fake.sub'), [
    fake.isError && !fg
      ? jsxs('p', { className: 'sel-inline', role: 'alert', children: [t('err.fake'), jsx(Retry, { t, onClick: () => fake.refetch() })] }, 'x')
      : !fg
        ? jsx('p', { className: 'sel-inline', children: t('fake.loading') }, 'l')
        : jsxs(Fragment, { children: [
            fg.summary?.headline ? jsx('p', { className: 'sel-load-why', style: { margin: 0 }, children: fg.summary.headline }, 'h') : null,
            fgCards.length === 0
              ? jsx('p', { className: 'sel-inline', children: t('fake.none') }, 'e')
              : jsx('ol', { className: 'sel-rows', children: fgCards.map(c => jsxs('li', { className: 'sel-fg', children: [
                  jsx('span', { className: 'sel-fg-title', title: c.title || c.id, children: c.title || c.id }),
                  jsx('span', { className: 'sel-tag', children: c.label }),
                  jsxs('span', { className: 'sel-when', style: { textAlign: 'right' }, children: [jsx('span', { 'aria-hidden': true, children: t('fake.age', c.age_h) }), jsx('span', { className: 'sel-sr', children: t('fake.ageLong', c.age_h) })] })
                ] }, c.id)) }, 'c')
          ] }, 'b')
  ])
  const prop = proposal.data?.proposal

  // A fresh install has no ledger yet; Cleanse and the board audit still work.
  if (!o.has_ledger) {
    return shell([head, warn, jsx('div', { className: 'sel-card', children: jsx(EmptyState, { title: t('empty.title'), description: t('empty.body') }) }, 'e'), cleanseSec, fakeSec])
  }

  return shell([
    head,
    warn,
    jsxs('section', { className: 'sel-card sel-load', 'data-load': lk, 'aria-labelledby': 'sel-load-h', children: [
      jsx(Meter, { load: lk }),
      jsxs('div', { style: { minWidth: 0 }, children: [
        jsxs('h2', { id: 'sel-load-h', className: 'sel-load-state', style: { margin: 0 }, children: [t('load.prefix'), jsx('span', { children: t(`load.${lk}`) })] }),
        jsx('div', { className: 'sel-load-why', children: t(`load.${LOAD[lk].why}`, o.calm_24h ?? 0) })
      ] }),
      jsx('div', { style: { marginLeft: 'auto' }, className: 'sel-when', children: o.last_calm ? t('load.last', ago(o.last_calm)) : '' })
    ] }),
    // Announced only when the load word changes, never on each 30 s refetch.
    jsx(LoadAnnouncer, { text: `${t('load.prefix')}${t(`load.${lk}`)}` }),
    jsxs('section', { className: 'sel-stats', 'aria-label': t('stats.label'), children: [
      stat(t('stats.gates'), tot.gates, 'gate', t('stats.kinds', gates.length)),
      stat(t('stats.approvals'), tot.approvals, 'approval'),
      stat(t('stats.calm'), tot.calm, 'calm'),
      stat(t('stats.fixes'), tot.fixes, null)
    ] }),
    cleanseSec,
    jsxs('div', { className: 'sel-cols', children: [
      sec('sel-gates-h', t('gates.title'), t('gates.sub'), [gates.length === 0
        ? jsx(EmptyState, { title: t('empty.gatesTitle'), description: t('empty.gatesBody') }, 'e')
        : jsx('ol', { className: 'sel-rows', children: gates.slice(0, 10).map((g, i) => jsxs('li', { className: 'sel-row', children: [
            jsx('span', { className: 'sel-rank', 'aria-hidden': true, children: i + 1 }),
            jsxs('div', { style: { minWidth: 0 }, children: [
              jsx('div', { className: 'sel-key', children: g.key }),
              jsx('div', { className: 'sel-note', children: g.note || t('gates.last', ago(g.last)) })
            ] }),
            jsx('div', { className: 'sel-bar', 'aria-hidden': true, children: jsx('i', { style: { width: `${(100 * (Number(g.n) || 0)) / maxN}%` } }) }),
            jsxs('span', { className: 'sel-count', children: [jsx('span', { 'aria-hidden': true, children: `×${g.n}` }), jsx('span', { className: 'sel-sr', children: t('gates.times', g.n) })] }),
            g.fixed
              ? jsx('span', { className: 'sel-fixed', children: t('gates.fixed') })
              : jsx(Button, { size: 'xs', variant: 'ghost', 'aria-label': t('gates.markKey', g.key),
                  disabled: markFix.isPending && markFix.variables === g.key, onClick: () => markFix.mutate(g.key), children: t('gates.mark') })
          ] }, g.key)) }, 'l')]),
      jsxs('div', { className: 'sel-sec', children: [
        fakeSec,
        sec('sel-evolve-h', t('evolve.title'), prop ? t('evolve.drafted', ago(prop.mtime)) : t('evolve.none'), [
          proposal.isError && !prop
            ? jsxs('p', { className: 'sel-inline', role: 'alert', children: [t('err.proposal'), jsx(Retry, { t, onClick: () => proposal.refetch() })] }, 'x')
            : prop
              ? jsx(Proposal, { text: prop.text, label: t('evolve.region') }, 'p')
              : jsx('p', { className: 'sel-load-why', style: { margin: 0 }, children: t('evolve.about') }, 'a'),
          jsxs('div', { className: 'sel-actions', children: [
            jsx(Button, { size: 'sm', variant: 'secondary', disabled: draft.isPending, onClick: () => draft.mutate(), children: draft.isPending ? t('evolve.drafting') : t('evolve.draft') }),
            jsx(CopyButton, { text: '/frictionless evolve', label: t('evolve.copy'), showLabel: true, appearance: 'button', buttonVariant: 'ghost', buttonSize: 'sm' })
          ] }, 'b')
        ]),
        sec('sel-sig-h', t('signals.title'), t('signals.sub'), [
          jsx('ul', { className: 'sel-sigs', children: Object.entries(o.signals ?? {}).map(([k, n]) => jsxs('li', {
            className: 'sel-sig', 'data-silent': n ? undefined : '', children: [k.replace(/_/g, ' '), jsx('b', { children: n }), n ? null : jsx('span', { children: `(${t('signals.silent')})` })]
          }, k)) }, 's')
        ])
      ] })
    ] }),
    sec('sel-ledger-h', t('ledger.title'), null, [
      events.isError && !events.data
        ? jsxs('p', { className: 'sel-inline', role: 'alert', children: [t('err.ledger'), jsx(Retry, { t, onClick: () => events.refetch() })] }, 'x')
        : evs.length === 0 && events.data
          ? jsx('p', { className: 'sel-inline', children: t('empty.ledger') }, 'e')
          : jsx('ul', { className: 'sel-rows', children: keyed(evs, e => `${e.ts}-${e.kind}-${e.key}`).map(([k, e]) => jsxs('li', { className: 'sel-ev', children: [
              jsx('span', { className: 'sel-dot', 'data-k': e.kind, 'aria-hidden': true }),
              jsx('span', { className: 'sel-kind', children: kindLabel(e.kind) }),
              jsx('span', { className: 'sel-key', children: e.key }),
              jsx('span', { className: 'sel-note', children: e.note }),
              jsx('span', { className: 'sel-when', children: ago(e.ts) })
            ] }, k)) }, 'l')
    ])
  ])
}

// A polite live region whose text changes only when the value does.
function LoadAnnouncer({ text }) {
  const [said, setSaid] = useState(null)
  useEffect(() => { setSaid(prev => (prev === null ? '' : text)) }, [text])
  return jsx('div', { className: 'sel-sr', 'aria-live': 'polite', children: said })
}

// --- status chip -------------------------------------------------------------

function Chip({ prefs, status }) {
  const t = useT()
  const { showChip, chipStyle } = useValue(prefs)
  const s = useValue(status)
  if (!showChip || !s) return null
  const open = Number(s.open_today) || 0
  const tip = t('chip.status', t(`load.${loadKey(s.load)}`).toLowerCase(), open)
  // Name says what it does; the tooltip (announced as the description) says the state.
  return jsx(Tip, { label: tip, children: jsxs('button', {
    type: 'button', className: STATUSBAR_BTN, 'aria-label': t('chip.open'), onClick: () => host.navigate(PATH),
    children: [jsx(Blade, { size: 12 }), chipStyle === 'count' && open ? jsx('span', { className: 'sel-chip-n', children: open }) : null]
  }) })
}

// --- settings ----------------------------------------------------------------

function Settings({ prefs, update, status }) {
  const t = useT()
  const { showChip, chipStyle, kanbanBadges } = useValue(prefs)
  const dir = useValue(status)?.state_dir || '~/.local/state/selenite'
  return jsxs('div', { children: [
    jsx(ToggleRow, { label: t('settings.chip'), description: t('settings.chipBody'), checked: showChip, onChange: on => update({ showChip: on }) }),
    jsx(ListRow, { title: t('settings.style'), description: t('settings.styleBody'),
      action: jsx(SegmentedControl, { value: chipStyle, onChange: v => update({ chipStyle: v }), options: [{ id: 'count', label: t('settings.count') }, { id: 'glyph', label: t('settings.glyph') }] }) }),
    jsx(ToggleRow, { label: t('settings.kanban'), description: t('settings.kanbanBody'), checked: kanbanBadges, onChange: on => update({ kanbanBadges: on }) }),
    jsx(ListRow, { title: t('settings.privacy'), description: t('settings.privacyBody', dir) })
  ] })
}

// --- register ----------------------------------------------------------------

const DEFAULTS = { days: 30, showChip: true, chipStyle: 'count', kanbanBadges: true }

// Stored prefs are untrusted: keep only known keys with valid values.
function cleanPrefs(raw) {
  const p = raw && typeof raw === 'object' ? raw : {}
  return {
    days: [7, 30, 90].includes(p.days) ? p.days : DEFAULTS.days,
    showChip: typeof p.showChip === 'boolean' ? p.showChip : DEFAULTS.showChip,
    chipStyle: p.chipStyle === 'glyph' || p.chipStyle === 'count' ? p.chipStyle : DEFAULTS.chipStyle,
    kanbanBadges: typeof p.kanbanBadges === 'boolean' ? p.kanbanBadges : DEFAULTS.kanbanBadges
  }
}

export default {
  id: ID,
  name: 'Selenite',
  register(ctx) {
    let stored
    try { stored = ctx.storage.get('prefs', {}) } catch { stored = {} }
    const prefs = atom(cleanPrefs(stored))
    const update = patch => { prefs.set(cleanPrefs({ ...prefs.get(), ...patch })); ctx.storage.set('prefs', prefs.get()) }
    ctx.i18n?.register?.(LOCALES)
    const tNow = (key, ...a) => (ctx.i18n?.t ? ctx.i18n.t(key, ...a) : enT(key, ...a))

    const style = document.createElement('style')
    style.dataset.plugin = ID
    style.textContent = CSS
    document.head.appendChild(style)
    ctx.onDispose(() => style.remove())

    // One small poll feeds the chip and the Kanban badges (decorate() must be
    // synchronous). The page keeps its own window-sized queries.
    const status = atom(null)
    const pull = () => {
      const { showChip, kanbanBadges } = prefs.get()
      if (!showChip && !kanbanBadges) return Promise.resolve()
      return ctx.rest('/status').then(s => { if (s && typeof s === 'object') status.set(s) }, () => {})
    }
    pull()
    ctx.setInterval(pull, 60_000)
    let was = prefs.get()
    const unlisten = prefs.listen?.(() => {
      const now = prefs.get()
      if ((now.showChip && !was.showChip) || (now.kanbanBadges && !was.kanbanBadges)) pull()
      was = now
    })
    if (typeof unlisten === 'function') ctx.onDispose(unlisten)
    const blocked = () => new Set(status.get()?.blocked_tasks ?? [])

    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: PATH }, render: () => jsx(SelenitePage, { ctx, prefs, update, refreshStatus: pull }) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: PATH, label: tNow('name'), codicon: 'wand' } },
      { id: 'chip', area: STATUSBAR_AREAS.right, order: 105, render: () => jsx(Chip, { prefs, status }) },
      { id: 'open', area: PALETTE_AREA, data: { id: 'selenite.open', label: tNow('palette.open'), keywords: ['friction', 'gate', 'calm', 'ledger'], run: () => host.navigate(PATH) } },
      { id: 'cleanse', area: PALETTE_AREA, data: { id: 'selenite.cleanse', label: tNow('palette.cleanse'), keywords: ['cleanse', 'clear', 'audit', 'sweep'],
        run: () => ctx.rest(`/cleanse?days=${prefs.get().days}`, { method: 'POST' }).then(() => host.navigate(PATH), fail(tNow('err.cleanse'))) } },
      { id: 'draft', area: PALETTE_AREA, data: { id: 'selenite.draft', label: tNow('palette.draft'), keywords: ['evolve', 'proposal', 'improve'],
        run: () => ctx.rest(`/proposal?days=${prefs.get().days}`, { method: 'POST' }).then(() => host.navigate(PATH), fail(tNow('err.draft'))) } },
      ...(KANBAN_CARD_AREAS?.badges ? [{ id: 'waiting', area: KANBAN_CARD_AREAS.badges, data: {
        decorate: card => (prefs.get().kanbanBadges && blocked().has(card.id)
          ? { label: tNow('kanban.badge'), tone: 'neutral', tooltip: tNow('kanban.tip') }
          : null)
      } }] : [])
    ])

    ctx.registerSettingsPage?.({ id: 'settings', title: tNow('name'), icon: 'wand', render: () => jsx(Settings, { prefs, update, status }) })
  }
}
